 function snapshot(cards: ReviewCard[], warnings: string[] = []): ReviewBoardSnapshot {
   return { version: 1, repo: "org/repo", repositories: ["org/repo"], repositoryId: "repo1", viewer: "ann", fetchedAt: pr.updatedAt, cards, warnings };
 }

